using System;using System.IO;using System.Diagnostics;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;
namespace PZ3D {
 sealed class ServerWorkshopPreparation:IDisposable {
  sealed class Item {public string id,state="pending",message="";}
  sealed class Snapshot {public int protocol=1,revision,totalItems,completedItems,progress=-1;public string jobId,serverId,endpoint,manifestStamp,state="running",currentItem="",message="正在准备";public Item[] items;}
  sealed class Saved {public int ownerPid;public long ownerBirth;public Snapshot snapshot;}
  readonly object gate=new object();readonly string data;readonly Action<object> publish;Snapshot snapshot;CancellationTokenSource cancellation;Task worker;bool disposed;
  public ServerWorkshopPreparation(string data,Action<object> publish){this.data=data;this.publish=publish;string folder=Path.Combine(data,"server-workshop-jobs");LauncherMaintenance.NoReparse(folder);if(Directory.Exists(folder)){string file=Directory.GetFiles(folder,"*.json").OrderByDescending(File.GetLastWriteTimeUtc).FirstOrDefault();if(file!=null){var saved=LauncherNativeState.Read<Saved>(file,()=>null);if(saved==null||saved.snapshot==null||saved.snapshot.protocol!=1||saved.snapshot.items==null||saved.snapshot.items.Length>2000||!System.Text.RegularExpressions.Regex.IsMatch(saved.snapshot.jobId??"",@"^[a-f0-9]{32}$")||Path.GetFileNameWithoutExtension(file)!=saved.snapshot.jobId||!new[]{"running","completed","partial","failed","cancelled","interrupted"}.Contains(saved.snapshot.state)||saved.snapshot.totalItems!=saved.snapshot.items.Length)throw new Exception("准备任务记录无效。");bool alive=false;try{using(var p=Process.GetProcessById(saved.ownerPid))alive=!p.HasExited&&p.StartTime.ToUniversalTime().Ticks==saved.ownerBirth;}catch{}if(saved.snapshot.state!="running"||!alive){snapshot=saved.snapshot;if(snapshot.state=="running"){snapshot.state="interrupted";snapshot.progress=-1;snapshot.message="上次准备任务中断，请重新核实清单后准备。";snapshot.revision++;Save();}}}}}
  void Save(){using(var process=Process.GetCurrentProcess())LauncherNativeState.Write(Path.Combine(data,"server-workshop-jobs",snapshot.jobId+".json"),new Saved{ownerPid=process.Id,ownerBirth=process.StartTime.ToUniversalTime().Ticks,snapshot=snapshot});}
  public bool Active{get{lock(gate)return worker!=null&&!worker.IsCompleted;}}
  object Copy(){return snapshot==null?null:new JavaScriptSerializer().DeserializeObject(new JavaScriptSerializer().Serialize(snapshot));}
  public object Status(){lock(gate)return Copy();}
  void Changed(){snapshot.revision++;if(publish!=null)try{publish(Copy());}catch{/* Closing views must not orphan the owned worker. */}}
  public object Start(string serverId,ServerWorkshopManifest manifest,Func<string,Action<int,string>,CancellationToken,object> download){lock(gate){if(disposed)throw new ObjectDisposedException("ServerWorkshopPreparation");if(worker!=null&&!worker.IsCompleted){if(snapshot.serverId==serverId&&snapshot.manifestStamp==manifest.stamp)return Copy();throw new Exception("已有服务器准备任务，请先取消或等待完成。");}if(cancellation!=null)cancellation.Dispose();cancellation=new CancellationTokenSource();var token=cancellation.Token;
   var journal=new LauncherJournal(data);string jobId=journal.Begin("serverWorkshopPrepare","服务器工坊准备");snapshot=new Snapshot{jobId=jobId,serverId=serverId,endpoint=manifest.endpoint,manifestStamp=manifest.stamp,totalItems=manifest.ids.Length,items=manifest.ids.Select(id=>new Item{id=id}).ToArray()};try{Save();}catch(Exception e){snapshot.state="failed";snapshot.message=e.Message;journal.Finish("failed",e.Message);throw;}Changed();worker=Task.Factory.StartNew(()=>Run(download,journal,token),CancellationToken.None,TaskCreationOptions.LongRunning,TaskScheduler.Default);return Copy();}}
  void Run(Func<string,Action<int,string>,CancellationToken,object> download,LauncherJournal journal,CancellationToken token){
   try{foreach(var item in snapshot.items){token.ThrowIfCancellationRequested();lock(gate){snapshot.currentItem=item.id;snapshot.progress=-1;item.state="running";snapshot.message="正在处理工坊项目 "+item.id;Changed();}
    try{object result=download(item.id,(value,text)=>{token.ThrowIfCancellationRequested();journal.Update(value,text);lock(gate){snapshot.progress=value<0?-1:Math.Min(value,100);snapshot.message=LauncherJournal.Sanitize(text);Changed();}},token);token.ThrowIfCancellationRequested();var resultMap=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new JavaScriptSerializer().Serialize(result));object resultId;if(resultMap==null||!resultMap.TryGetValue("id",out resultId)||!(resultId is string)||(string)resultId!=item.id)throw new Exception("Steam 未返回已核实的项目结果。");lock(gate){item.state="completed";item.message="订阅与安装已核实";snapshot.completedItems++;Changed();}}
    catch(OperationCanceledException){throw;}catch(Exception e){lock(gate){item.state="failed";item.message=LauncherJournal.Sanitize(e.Message);snapshot.message=item.message;Changed();}journal.Update(-1,item.id+" · "+e.Message);}
   }token.ThrowIfCancellationRequested();lock(gate){snapshot.state=snapshot.completedItems==snapshot.totalItems?"completed":snapshot.completedItems==0?"failed":"partial";snapshot.currentItem="";snapshot.progress=snapshot.state=="completed"?100:-1;snapshot.message=snapshot.state=="completed"?"所有项目订阅与安装已核实。":"部分项目未完成，请检查各项结果。";}}
   catch(OperationCanceledException){lock(gate){snapshot.state="cancelled";snapshot.message="已取消；已完成的订阅和文件保留。";snapshot.progress=-1;foreach(var item in snapshot.items.Where(i=>i.state=="running"))item.state="cancelled";}}
   catch(Exception e){lock(gate){snapshot.state="failed";snapshot.progress=-1;snapshot.message=LauncherJournal.Sanitize(e.Message);}}
   finally{try{lock(gate)Save();}catch(Exception e){lock(gate){snapshot.state="failed";snapshot.message="任务快照写入失败："+LauncherJournal.Sanitize(e.Message);}}try{journal.Finish(snapshot.state,snapshot.message);}catch(Exception e){lock(gate){snapshot.state="failed";snapshot.message="任务记录写入失败："+LauncherJournal.Sanitize(e.Message);}}lock(gate)Changed();}
  }
  public object Cancel(string jobId){lock(gate){if(snapshot==null||snapshot.jobId!=jobId)throw new Exception("准备任务已变化，请刷新。");if(worker!=null&&!worker.IsCompleted)cancellation.Cancel();return Copy();}}
  public void Drain(){Task owned;lock(gate){owned=worker;if(owned!=null&&!owned.IsCompleted)cancellation.Cancel();}if(owned!=null&&!owned.Wait(10000))throw new Exception("工坊准备尚未释放，请稍后重试。");}
  public void Dispose(){lock(gate)disposed=true;Drain();lock(gate){if(cancellation!=null)cancellation.Dispose();}}
 }
}
